#!/usr/bin/env node
/**
 * Encode generated dry masters into game voice lines and rebuild the manifest.
 *
 *     node scripts/voice/encode-voice-lines.mjs [--locale en] [--force]
 *
 * Reads art/source/voice/lines/<locale>/<key>.wav (dry masters from
 * scripts/voice/qwen_voice.py, never modified), applies the role's post chain
 * from the casting bible section 17, loudness-normalizes, and writes mono MP3s
 * to public/audio/voice/lines/<locale>/<key>.mp3. The manifest
 * (public/audio/voice/lines/manifest.json) lists exactly the keys present, so
 * src/voiceLines.js only offers lines that exist.
 */
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const MASTERS = path.join(ROOT, 'art/source/voice/lines');
const OUT = path.join(ROOT, 'public/audio/voice/lines');
const LINES = path.join(ROOT, 'scripts/voice/voice-lines.json');

const NORMALIZE = 'loudnorm=I=-18:TP=-1.5:LRA=9';
const CLEAN = 'highpass=f=80,acompressor=threshold=-20dB:ratio=2.5:attack=8:release=120';

// Casting bible section 17, as ffmpeg filter chains. The dry master is kept.
const CHAINS = {
    // Communications band-pass, light compression.
    mothership: 'highpass=f=300,lowpass=f=3400,acompressor=threshold=-18dB:ratio=3:attack=5:release=90',
    // Minimal EQ.
    system: 'highpass=f=110,acompressor=threshold=-20dB:ratio=2:attack=6:release=100',
    // Short industrial reflection, subtle low resonance.
    bunker: `${CLEAN},bass=g=2:f=110,aecho=0.8:0.7:38:0.18`,
    // Quiet double, restrained width, subtle harmonic bed.
    queen: `${CLEAN},chorus=0.7:0.9:22:0.22:0.25:1.6,aecho=0.8:0.6:60:0.12`,
    // Human cast: light cleanup, leveling. No pitch shifts.
    martha: CLEAN,
    briggs: CLEAN,
    kaelen: CLEAN,
    okonkwo: CLEAN,
    // Hive allies: each its own quiet double or resonance.
    nahl: `${CLEAN},chorus=0.75:0.9:30:0.2:0.2:1.2`,
    vey: `${CLEAN},aecho=0.8:0.55:12:0.2`,
    rhun: `${CLEAN},bass=g=3:f=90,aecho=0.8:0.6:48:0.14`,
    developer: CLEAN
};

/** ffmpeg -af chain for a role (and suit register, for System). */
export function filterChainFor(role, register = null) {
    const base = CHAINS[role] ?? CLEAN;
    // Controlled digital breakup for the infected suit; never baked into the master.
    const glitch = role === 'system' && register === 'glitched' ? ',acrusher=bits=11:mix=0.18:mode=log' : '';
    return `${base}${glitch},${NORMALIZE}`;
}

/** Manifest of the keys with an encoded line, per locale. */
export function buildManifest(outDir = OUT) {
    const locales = {};
    if (fs.existsSync(outDir)) {
        for (const locale of fs.readdirSync(outDir).sort()) {
            const dir = path.join(outDir, locale);
            if (!fs.statSync(dir).isDirectory()) continue;
            const keys = fs.readdirSync(dir).filter((f) => f.endsWith('.mp3')).map((f) => f.slice(0, -4)).sort();
            if (keys.length) locales[locale] = keys;
        }
    }
    return {
        note: 'Generated by scripts/voice (docs/voice-generation-pipeline.md). Lists the i18n keys with recorded audio per locale.',
        locales
    };
}

function main() {
    const args = process.argv.slice(2);
    const only = args.includes('--locale') ? args[args.indexOf('--locale') + 1] : null;
    const force = args.includes('--force');
    const byKey = new Map(JSON.parse(fs.readFileSync(LINES, 'utf8')).lines.map((l) => [`${l.locale}/${l.key}`, l]));
    let encoded = 0;
    if (fs.existsSync(MASTERS)) {
        for (const locale of fs.readdirSync(MASTERS)) {
            if (only && locale !== only) continue;
            for (const file of fs.readdirSync(path.join(MASTERS, locale)).filter((f) => f.endsWith('.wav'))) {
                const key = file.slice(0, -4);
                const line = byKey.get(`${locale}/${key}`);
                if (!line) { console.warn(`[voice-encode] ${locale}/${key}: not in voice-lines.json; skipped`); continue; }
                const out = path.join(OUT, locale, `${key}.mp3`);
                if (fs.existsSync(out) && !force) continue;
                fs.mkdirSync(path.dirname(out), { recursive: true });
                execFileSync('ffmpeg', ['-y', '-loglevel', 'error', '-i', path.join(MASTERS, locale, file),
                    '-af', filterChainFor(line.role, line.register), '-ac', '1', '-ar', '44100',
                    '-codec:a', 'libmp3lame', '-q:a', '4', out]);
                encoded += 1;
            }
        }
    }
    fs.writeFileSync(path.join(OUT, 'manifest.json'), `${JSON.stringify(buildManifest(), null, 2)}\n`);
    console.log(`[voice-encode] ${encoded} lines encoded; manifest rebuilt`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) main();
